import { useState, useEffect, useRef } from "react";
import { apiFetch, apiUpload } from "../utils/api";

const BASE = "http://localhost:8000";

const Icons = {
  doc: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>,
  upload: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><polyline points="16 16 12 12 8 16"/><line x1="12" y1="12" x2="12" y2="21"/><path d="M20.39 18.39A5 5 0 0018 9h-1.26A8 8 0 103 16.3"/></svg>,
  home: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>,
  docs: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>,
  check: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>,
  download: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>,
  audit: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>,
  x: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>,
  pen: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 013 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>,
};

function StatusBadge({ status }) {
  return (
    <span className={`badge badge-${status}`}>
      <span className="badge-dot"></span>
      {status}
    </span>
  );
}

function AuditModal({ docId, token, onClose }) {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    apiFetch(`/api/audit/${docId}`, {}, token)
      .then(setLogs).catch(console.error).finally(() => setLoading(false));
  }, [docId, token]);

  const dotClass = (action) => {
    if (action === "signed")   return "audit-dot audit-dot-signed";
    if (action === "rejected") return "audit-dot audit-dot-rejected";
    if (action === "viewed")   return "audit-dot audit-dot-viewed";
    return "audit-dot audit-dot-upload";
  };
  const dotIcon = (action) => {
    if (action === "signed")   return "✓";
    if (action === "rejected") return "✕";
    if (action === "viewed")   return "👁";
    return "↑";
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={e => e.stopPropagation()}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"1.5rem" }}>
          <div>
            <div className="modal-title">Audit Trail</div>
            <div className="modal-sub" style={{margin:0}}>Complete activity log for this document</div>
          </div>
          <button onClick={onClose} style={{ background:"none", border:"none", cursor:"pointer", color:"#9CA3AF", padding:"4px" }}>
            {Icons.x}
          </button>
        </div>
        {loading ? (
          <div style={{ textAlign:"center", padding:"2rem" }}><span className="spinner"></span></div>
        ) : (
          <div className="audit-list">
            {logs.map((log, i) => (
              <div key={log.id} className="audit-item" style={{ animationDelay: `${i * 0.05}s` }}>
                <div className={dotClass(log.action)}>{dotIcon(log.action)}</div>
                <div>
                  <div className="audit-action">{log.action}</div>
                  {log.detail && <div className="audit-detail">{log.detail}</div>}
                  <div className="audit-time">
                    {new Date(log.timestamp).toLocaleString()} · {log.ip_address}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function RejectModal({ sig, token, onClose, onDone }) {
  const [reason, setReason] = useState("");
  const [loading, setLoading] = useState(false);

  const handleReject = async () => {
    setLoading(true);
    try {
      await apiFetch("/api/signatures/finalize", { method:"POST", body: JSON.stringify({ signature_id: sig.id, action:"reject", reason }) }, token);
      onDone();
    } catch(err) { alert(err.message); }
    finally { setLoading(false); }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={e => e.stopPropagation()}>
        <div className="modal-title">Reject Document</div>
        <div className="modal-sub">Provide a reason for rejection (optional)</div>
        <textarea className="form-input" rows={4} placeholder="e.g. Incorrect clause in section 3..."
          value={reason} onChange={e => setReason(e.target.value)}
          style={{ resize:"vertical", fontFamily:"var(--font-body)" }} />
        <div className="modal-actions">
          <button className="btn-cancel" onClick={onClose}>Cancel</button>
          <button className="btn-danger" onClick={handleReject} disabled={loading}>
            {loading ? <span className="spinner"></span> : "Confirm Rejection"}
          </button>
        </div>
      </div>
    </div>
  );
}

export default function Dashboard({ token, onLogout }) {
  const [docs, setDocs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [filter, setFilter] = useState("all");
  const [auditDocId, setAuditDocId] = useState(null);
  const [rejectSig, setRejectSig] = useState(null);
  const [signingId, setSigningId] = useState(null);
  const [dragOver, setDragOver] = useState(false);
  const fileRef = useRef();

  const fetchDocs = async () => {
    try {
      const url = filter === "all" ? "/api/docs" : `/api/docs?status=${filter}`;
      const data = await apiFetch(url, {}, token);
      setDocs(data);
    } catch(err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { setLoading(true); fetchDocs(); }, [filter]);

  const handleUpload = async (file) => {
    if (!file || !file.name.endsWith(".pdf")) { alert("Please upload a PDF file"); return; }
    setUploading(true);
    try {
      const form = new FormData();
      form.append("file", file);
      const doc = await apiUpload("/api/docs/upload", form, token);
      // auto-place a signature at standard position
      await apiFetch("/api/signatures", { method:"POST", body: JSON.stringify({ doc_id: doc.id, page: 0, x: 0.05, y: 0.82, width: 0.35, height: 0.07 }) }, token);
      setDocs(prev => [{ ...doc, _hasSig: true }, ...prev]);
    } catch(err) { alert(err.message); }
    finally { setUploading(false); }
  };

  const handleSign = async (doc) => {
    setSigningId(doc.id);
    try {
      // get signatures for this doc
      const sigs = await apiFetch(`/api/signatures/${doc.id}`, {}, token);
      const pending = sigs.find(s => s.status === "pending");
      if (!pending) { alert("No pending signature found"); return; }
      await apiFetch("/api/signatures/finalize", { method:"POST", body: JSON.stringify({ signature_id: pending.id, action: "sign" }) }, token);
      fetchDocs();
    } catch(err) { alert(err.message); }
    finally { setSigningId(null); }
  };

  const handleRejectDone = () => { setRejectSig(null); fetchDocs(); };

  const handleDownload = async (doc) => {
    const res = await fetch(`${BASE}/api/docs/${doc.id}/download?signed=true`, { headers: { Authorization: `Bearer ${token}` } });
    if (!res.ok) { alert("Signed PDF not available yet"); return; }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `signed_${doc.filename}`; a.click();
    URL.revokeObjectURL(url);
  };

  const stats = {
    total:    docs.length,
    pending:  docs.filter(d => d.status === "pending").length,
    signed:   docs.filter(d => d.status === "signed").length,
  };

  const getUserInitials = () => {
    const stored = localStorage.getItem("username") || "U";
    return stored.slice(0,2).toUpperCase();
  };

  return (
    <div className="app-shell">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-logo">
          <div className="sidebar-logo-dot"></div>
          <span className="sidebar-logo-text">Doc<span>Sign</span></span>
        </div>
        <div className="sidebar-section">
          <div className="sidebar-label">Menu</div>
          <button className="sidebar-item active">{Icons.home}<span>Dashboard</span></button>
          <button className="sidebar-item">{Icons.docs}<span>Documents</span></button>
          <button className="sidebar-item">{Icons.pen}<span>Sign</span></button>
          <button className="sidebar-item">{Icons.audit}<span>Audit Logs</span></button>
        </div>
        <div className="sidebar-footer">
          <div className="sidebar-user">
            <div className="sidebar-avatar">{getUserInitials()}</div>
            <div>
              <div className="sidebar-username">My Account</div>
              <div className="sidebar-email">Signed in</div>
            </div>
          </div>
          <button className="sidebar-logout" onClick={onLogout}>Sign out</button>
        </div>
      </aside>

      {/* Main */}
      <main className="main-content">
        <div className="topbar">
          <div className="topbar-title">Dashboard</div>
          <div className="topbar-right">
            <button className="btn-sm btn-sign" onClick={() => fileRef.current.click()} disabled={uploading}>
              {uploading ? <span className="spinner"></span> : `+ Upload PDF`}
            </button>
            <input ref={fileRef} type="file" accept=".pdf" style={{ display:"none" }} onChange={e => { handleUpload(e.target.files[0]); e.target.value=""; }} />
          </div>
        </div>

        <div className="page-content">
          {/* Stats */}
          <div className="stats-row" style={{ marginBottom:"1.5rem" }}>
            <div className="stat-card animate-fadeUp">
              <div className="stat-icon" style={{ background:"rgba(99,102,241,0.1)" }}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#6366F1" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              </div>
              <div>
                <div className="stat-num">{stats.total}</div>
                <div className="stat-label">Total Documents</div>
              </div>
            </div>
            <div className="stat-card animate-fadeUp" style={{ animationDelay:"0.1s" }}>
              <div className="stat-icon" style={{ background:"rgba(245,158,11,0.1)" }}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#F59E0B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
              </div>
              <div>
                <div className="stat-num">{stats.pending}</div>
                <div className="stat-label">Awaiting Signature</div>
              </div>
            </div>
            <div className="stat-card animate-fadeUp" style={{ animationDelay:"0.2s" }}>
              <div className="stat-icon" style={{ background:"rgba(16,185,129,0.1)" }}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#10B981" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
              </div>
              <div>
                <div className="stat-num">{stats.signed}</div>
                <div className="stat-label">Signed & Complete</div>
              </div>
            </div>
          </div>

          {/* Upload zone */}
          <div className={`upload-zone${dragOver?" drag-over":""}`}
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={e => { e.preventDefault(); setDragOver(false); handleUpload(e.dataTransfer.files[0]); }}
            onClick={() => fileRef.current.click()}
            style={{ marginBottom:"1.5rem" }}
          >
            <div className="upload-icon">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#6366F1" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><polyline points="16 16 12 12 8 16"/><line x1="12" y1="12" x2="12" y2="21"/><path d="M20.39 18.39A5 5 0 0018 9h-1.26A8 8 0 103 16.3"/></svg>
            </div>
            <div className="upload-title">Drop your PDF here</div>
            <div className="upload-sub">or click to browse · PDF files only</div>
            {uploading && <div className="upload-progress"><div className="upload-progress-bar"></div></div>}
          </div>

          {/* Filter tabs */}
          <div className="filter-tabs">
            {["all","pending","signed","rejected"].map(f => (
              <button key={f} className={`filter-tab${filter===f?" active":""}`} onClick={() => setFilter(f)}>
                {f === "all" ? "All documents" : f.charAt(0).toUpperCase() + f.slice(1)}
              </button>
            ))}
          </div>

          {/* Documents */}
          <div className="section-title">
            {filter === "all" ? "All Documents" : filter} · {docs.length} file{docs.length !== 1 ? "s" : ""}
          </div>

          {loading ? (
            <div style={{ textAlign:"center", padding:"3rem" }}><span className="spinner"></span></div>
          ) : docs.length === 0 ? (
            <div className="empty-state">
              <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              <h3>No documents yet</h3>
              <p>Upload a PDF above to get started</p>
            </div>
          ) : (
            <div className="doc-grid">
              {docs.map((doc, i) => (
                <div key={doc.id} className="doc-card" style={{ animationDelay: `${i * 0.06}s` }}>
                  <div className="doc-icon" style={{ color:"#6366F1" }}>{Icons.doc}</div>
                  <div className="doc-info">
                    <div className="doc-name">{doc.filename}</div>
                    <div className="doc-meta">
                      Uploaded {new Date(doc.created_at).toLocaleDateString("en-IN", { day:"numeric", month:"short", year:"numeric" })}
                    </div>
                  </div>
                  <StatusBadge status={doc.status} />
                  <div className="doc-actions">
                    {doc.status === "pending" && (
                      <>
                        <button className="btn-sm btn-sign" onClick={() => handleSign(doc)} disabled={signingId === doc.id}>
                          {signingId === doc.id ? <span className="spinner"></span> : "✓ Sign"}
                        </button>
                        <button className="btn-sm btn-reject" onClick={async () => {
                          const sigs = await apiFetch(`/api/signatures/${doc.id}`, {}, token);
                          const pending = sigs.find(s => s.status === "pending");
                          if (pending) setRejectSig(pending);
                        }}>Reject</button>
                      </>
                    )}
                    {doc.status === "signed" && (
                      <button className="btn-sm btn-download" onClick={() => handleDownload(doc)}>
                        {Icons.download} Download
                      </button>
                    )}
                    <button className="btn-sm btn-view" onClick={() => setAuditDocId(doc.id)}>
                      {Icons.audit}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>

      {/* Modals */}
      {auditDocId && <AuditModal docId={auditDocId} token={token} onClose={() => setAuditDocId(null)} />}
      {rejectSig  && <RejectModal sig={rejectSig} token={token} onClose={() => setRejectSig(null)} onDone={handleRejectDone} />}
    </div>
  );
}
